mapper.select:
SELECT TASK_ID, CLIENT_ID, CREATE_TIME, NEXT_RETRY_AT
FROM (
	SELECT TASK_ID, CLIENT_ID, CREATE_TIME, NEXT_RETRY_AT
	FROM SYS_OAUTH_CLIENT_REVOKE_TASK
	WHERE NEXT_RETRY_AT <= #{now}
	ORDER BY NEXT_RETRY_AT, CREATE_TIME, TASK_ID
)
WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE SYS_OAUTH_CLIENT_REVOKE_TASK
SET NEXT_RETRY_AT = #{nextRetryAt}
WHERE TASK_ID = #{taskId}
AND NEXT_RETRY_AT < #{nextRetryAt}
